// One colour scheme, by role. Windows' app mode picks kDark or kLight; high
// contrast uses the user's own colours instead.
struct Scheme {
  // The page. Sections alternate between it and ground-deep.
  Argb ground;
  // A band a step below the ground, for the sections that alternate with it,
  // deep enough to show on a dim screen.
  Argb ground_deep;
  // A panel or a row on the ground.
  Argb raised;
  // A raised panel under the pointer, or a pressed control.
  Argb raised_2;
  // A well: code, checksums, the filter chain.
  Argb sunken;
  // The frame of a video or a screenshot: a well, like a screen that's off.
  Argb screen;
  // Hairlines: rules, row dividers, wires, gridlines.
  Argb line;
  // Control edges and titled rules.
  Argb line_strong;
  // Headlines, body text and names.
  Argb text;
  // Secondary text: the lede, notes, links in a list.
  Argb text_2;
  // Labels, captions and the legal lines, and idle icons and wires.
  Argb text_3;
  // Cap red as the action colour: solid buttons, outlined buttons' edges, the
  // main file's edge, the download step.
  Argb action;
  // A solid button under the pointer, lit a step.
  Argb action_hover;
  // Red words: an outlined button's label, a hovered link, a recommended file's
  // tag.
  Argb action_text;
  // Words and icons on a solid red button: graphite, never ink.
  Argb on_action;
  // A link's underline. The words keep their own colour; the underline says
  // it's a link.
  Argb link_underline;
  // A link's words under the pointer.
  Argb link_hover;
  // The focus ring, 2px wide and 2px outside the control.
  Argb focus;
  // Selected text's ground: a wash of cap red, under ink.
  Argb selection;
  // The footer band, cap red deep in both schemes: the page's one large field
  // of red, and a red the page already uses.
  Argb band;
  // Hairlines on the band.
  Argb band_line;
  // Control edges and titled rules on the band.
  Argb band_line_strong;
  // Every word, link and underline on the band, and the white one-colour
  // lockup. White on cap red deep is 4.5:1 with no margin, so small words take
  // weight 500.
  Argb on_band;
  // Selected text's ground on the band: a deeper red, under white.
  Argb band_selection;
  // The focus ring on the band.
  Argb band_focus;
  // knobs in a chart: its bars, lit in cap red.
  Argb chart_knobs;
  // OBS in a chart: an unlit grey beside knobs's lit red. In dark it is apart
  // from the red in lightness as well as hue.
  Argb chart_obs;
};

