// performs.
// cubic-bezier(0.2, 0, 0, 1)
inline constexpr float kEaseX1 = 0.2f;
inline constexpr float kEaseY1 = 0.0f;
inline constexpr float kEaseX2 = 0.0f;
inline constexpr float kEaseY2 = 1.0f;
// Feedback: a hover, a copy confirming, a disclosure opening.
inline constexpr float kFastMs = 160.0f;
// Structure: a state settling, a panel changing height, a marker moving to a
